with base as (select *, trim(event_type) as clean_event_type, coalesce(page, 'DIRECT') as page_filled from web_events where event_time >= to_date('2023-05-22')), flagged as (select *, case when lag(event_time) over (partition by page order by event_time, id) is null or event_time > lag(event_time) over (partition by page order by event_time, id) + interval '30' day then 1 else 0 end as is_new_burst from base), sessions_web_events as (select id, page, event_time, clean_event_type, sum(is_new_burst) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_id_2 from flagged) select date_trunc('year', event_time) as year_start, page, case when session_id_2 >= 7 then 'PREMIUM' else 'STANDARD' end as session_id_2_tier, count(distinct page) as distinct_pages, max(event_time) as last_event_time, count(*) filter (where page = '/checkout') as checkout_rows from sessions_web_events group by 1, 2, 3 order by checkout_rows nulls last
